			nameFormatted = nameFormatted + lastNamePartner;
			break;
		case 'PB':
			//if (typeof middleNamePartner !== 'undefined' && middleNamePartner) { nameFormatted = nameFormatted  + middleNamePartner + ' '  }
			nameFormatted = nameFormatted + lastNamePartner;
